#include "opensim/services/inventory_descendents.hpp"
#include <iostream>
using namespace opensim;using namespace services;
namespace {
framework::Uuid id(int n){auto tail=std::to_string(n);return framework::Uuid("00000000-0000-0000-0000-"+std::string(12-tail.size(),'0')+tail);}
std::string hex(std::string_view s){std::string out;constexpr char digits[]="0123456789abcdef";for(unsigned char c:s){out+=digits[c>>4];out+=digits[c&15];}return out;}
std::string unhex(const std::string& s){if(s=="-")return {};std::string out;for(std::size_t i=0;i<s.size();i+=2)out+=static_cast<char>(std::stoi(s.substr(i,2),nullptr,16));return out;}
InventoryItem item(int n,int type){InventoryItem value;value.id=id(n);value.owner=id(100);value.parent=id(1);value.asset_id=id(type==24?700:500);value.asset_type=type;value.inventory_type=6;value.name="item<&>";value.description="description";value.flags=-1;return value;}
InventoryCollection collection(framework::Uuid key,int mode){InventoryCollection c;c.folder=(mode==4||mode==5)?framework::Uuid{}:key;c.owner=id(100);c.version=7;InventoryFolder f;f.id=id(900);f.parent=key;f.name="folder<&>";f.type=-1;f.version=0;c.folders.push_back(f);c.items={item(201,6),item(202,24)};return c;}
std::string probe(int mode,int options,const std::string& body){std::string trace;auto append=[&](const std::string& value){if(!trace.empty())trace+=';';trace+=value;};InventoryDescendentsBackend backend;
 backend.multiple_content=[&](auto owner,const auto& ids)->std::optional<InventoryDescendentsBackend::Collections>{std::string call="C"+owner.str();for(auto key:ids)call+=","+key.str();append(call);if(mode==6)throw std::runtime_error("provider");if(mode==1)return {};InventoryDescendentsBackend::Collections out;if(mode==2)return out;for(auto key:ids)out.push_back(mode==3?std::nullopt:std::optional{collection(key,mode)});if(mode==7)out.push_back(collection(id(20),0));if(mode==8&&!out.empty())out.pop_back();return out;};
 backend.folder=[&](auto owner,auto key)->std::optional<InventoryFolder>{append("F"+owner.str()+","+key.str());if(mode==5)return {};InventoryFolder f;f.id=key;f.owner=id(101);f.version=9;return f;};
 backend.multiple_items=[&](auto owner,const auto& ids)->std::optional<FetchInventory2Core::Items>{std::string call="I"+owner.str();for(auto key:ids)call+=","+key.str();append(call);if(options&16)throw std::runtime_error("link provider");if(options&4)return {};return FetchInventory2Core::Items{item(700,6),std::nullopt,item(701,24)};};
 if(!(options&2)){backend.library_owner=id(200);backend.library_content=[&](auto key)->std::optional<InventoryCollection>{append("L"+key.str());if(options&32)throw std::runtime_error("library provider");if(key==id(999))return {};auto c=collection(key,0);c.version=11;return c;};}
 FetchInventoryDescendentsCore core(std::move(backend));InventoryBadRequests bad([]{return 0;});if(options&1)bad.add(id(2));network::HttpRequest request;request.body=body;request.method="POST";std::string result;try{auto response=core.handle(request,options&8?nullptr:&bad);result=std::to_string(response.status)+":"+hex(response.body);}catch(const std::exception&){result="EXCEPTION";}return result+"|"+trace+"|"+(bad.contains(id(1))?"1":"0")+(bad.contains(id(2))?"1":"0")+(bad.contains(id(3))?"1":"0");}
std::string request(int key,bool folders=true,bool items=true,int owner=100){return "<llsd><map><key>folders</key><array><map><key>folder_id</key><uuid>"+id(key).str()+"</uuid><key>owner_id</key><uuid>"+id(owner).str()+"</uuid><key>fetch_folders</key><boolean>"+(folders?"1":"0")+"</boolean><key>fetch_items</key><boolean>"+(items?"1":"0")+"</boolean></map></array></map></llsd>";}
int count=0;void check(bool value,const char* label){++count;if(!value)throw std::runtime_error(label);}
void run(){check(probe(0,0,"bad").ends_with("||000"),"malformed XML empty response");check(probe(0,8,request(1)).ends_with("||000"),"null cache parse failure");check(probe(0,0,request(0)).ends_with("||000"),"zero folder never queries service");check(probe(3,0,request(1)).ends_with("|100"),"missing folder populates negative cache");check(probe(0,1,request(2)).ends_with("||010"),"cached folder avoids service");check(probe(6,0,request(1)).starts_with("EXCEPTION|C"),"provider errors propagate outside parse");check(probe(0,0,request(1)).find(";I")!=std::string::npos,"item link target fetched");check(probe(0,0,request(1,false,false)).find(";I")==std::string::npos,"suppressed items avoid link resolution");check(probe(0,0,request(1,false,false,200)).find("|L")!=std::string::npos,"library uses source library branch");check(probe(7,0,request(1)).starts_with("EXCEPTION"),"extra provider rows source index failure");}
}
int main(int argc,char**argv){try{if(argc==2&&std::string_view(argv[1])=="--probe"){int mode,options;std::string body;while(std::cin>>mode>>options>>body)std::cout<<probe(mode,options,unhex(body))<<'\n';return 0;}run();std::cout<<"PASS: "<<count<<" inventory descendents checks\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
